//This should be around 52 bits of entropy due to floating point precision.
//32 bit would work as well in this use case, but whatever.
let get_random_number = function(){
	let array = new Uint32Array(2);
	crypto.getRandomValues(array);
	
	let large_number = (array[0] * (2 ** 32) + array[1]);
	let small_number = (large_number / (2 ** 64));
	
	return small_number;
};

let get_rounded_hours = function(seconds){
	return (Math.round(seconds / 3600) + " hours");
};


let past_videos_allowed = video_ids.slice();
let past_videos_allowed_durations = durations.slice();
let past_videos_disallowed = [];
let past_videos_disallowed_durations = [];

let past_videos_total_duration = total_duration;

let past_video_limit = 200;


let add_past_video = function(index){
	past_videos_disallowed.unshift(past_videos_allowed[index]);
	past_videos_disallowed_durations.unshift(past_videos_allowed_durations[index]);
	
	past_videos_allowed.splice(index, 1);
	past_videos_allowed_durations.splice(index, 1);
	
    remove_overflowing_past_videos();
};

let remove_overflowing_past_videos = function(){
	if(past_video_limit < 0){
		return;
	}
	//console.log("removing too many, starts as ", past_videos_disallowed.slice());
    while(past_videos_disallowed.length > past_video_limit){
		//console.log(past_videos_disallowed.length, past_video_limit);
		past_videos_allowed.push(past_videos_disallowed.pop());
		past_videos_allowed_durations.push(past_videos_disallowed_durations.pop());
		//console.log("removed some", past_videos_disallowed.slice());
    }
	//console.log("removing too many finished", past_videos_disallowed.slice());
	
	
	past_videos_total_duration = 0;
	
	//let total = 0;
	
	for(let duration of past_videos_allowed_durations){
		past_videos_total_duration += duration;
	}
};

let get_random_video = function(){
	let video_id = "0bOsA93yYFk";
	let original_steps = (get_random_number() * past_videos_total_duration);
	let steps = original_steps;
    let last_index = 0;
    
    
    //Prevent infinite loop
    if(video_ids.length <= past_video_limit){
        past_video_limit = (video_ids.length - 1);
    }
	
    if(past_videos_total_duration === 0
    || past_videos_allowed.length === 0){
        return {
            video_id: video_id,
            seconds: 0
        };
    }
	
	
	if(settings.bad_random_algorithm === true){
		let video_index = Math.floor(get_random_number() * past_videos_allowed.length);
		let random_time = Math.floor(get_random_number() * past_videos_allowed_durations[video_index]);
		
		let video_id = past_videos_allowed[video_index];
        add_past_video(video_index);
		
		return {
            video_id: video_id,
            seconds: random_time
        };
	}
	
    while(true){
        for(let i = 0;;i = ((i + 1) % past_videos_allowed_durations.length)){
            if(steps > past_videos_allowed_durations[i]){
                steps -= past_videos_allowed_durations[i];
            } else {
                video_id = past_videos_allowed[i];
                last_index = i;
                break;
            }
        }
        
        
        add_past_video(last_index);
        break;
    }
    
	
	return ({
		video_id: video_id,
		seconds: steps
	});
};



let hide_container_elements = function(){
	loading_text_node.style.display = "none";
	instruction_text_node.style.display = "none";
	youtube_play_area_node.style.display = "none";
	about_text_node.style.display = "none";
};

